import { z } from 'zod';
import type { Registry } from '../src/core';

const fence = (value: unknown) =>
  `\`\`\`json\n${JSON.stringify(z.toJSONSchema(value as z.ZodType, { io: 'input', unrepresentable: 'any' }), null, 2)}\n\`\`\``;

/**
 * The exact shapes each registered panel and annotation accepts, as JSON
 * Schema. Generated from the same schemas the lint uses, so it cannot drift.
 */
export function skillReference(registry: Registry): string {
  const parts = [
    '# Panel and annotation shapes',
    '',
    'Generated by `pnpm skill` from the schemas the lint uses. Do not edit by hand.',
    '',
  ];
  for (const id of registry.panelIds()) {
    const panel = registry.panel(id)!;
    parts.push(`## Panel \`${id}\``, '', '`content`:', '', fence(panel.schema.content), '');
    if (panel.schema.effect !== undefined) {
      parts.push(
        'An effect on this panel takes the shared verbs plus these keys:',
        '',
        fence(panel.schema.effect),
        '',
      );
    } else {
      parts.push('Effects on this panel take the shared verbs only.', '');
    }
  }
  for (const id of registry.annotationIds()) {
    const plugin = registry.annotation(id)!;
    parts.push(
      `## Annotation \`${id}\``,
      '',
      `Walkthrough-level config, at \`annotations.${id}\`:`,
      '',
      fence(plugin.schema.config),
      '',
      `Per call, at \`steps[].calls[].annotations.${id}\`:`,
      '',
      fence(plugin.schema.call),
      '',
    );
  }
  return parts.join('\n');
}
